UPDATE mq_consume_log
SET status = 'OK', last_error = NULL, updated_at = NOW()
WHERE id = #{id} AND status = 'PROCESSING' AND lease_token = #{leaseToken}

UPDATE mq_consume_log
SET status = 'FAIL', last_error = #{error}, updated_at = NOW()
WHERE id = #{id} AND status = 'PROCESSING' AND lease_token = #{leaseToken}

UPDATE mq_consume_log
SET lease_token = #{newLeaseToken},
    attempt_count = attempt_count + 1,
    last_error = NULL,
    updated_at = NOW()
WHERE id = #{id}
  AND status = 'PROCESSING'


      AND lease_token IS NULL


      AND lease_token = #{observedLeaseToken}


  AND updated_at < #{staleBefore}
